#!/bin/bash

# Writes user-local Papirus folder icons (~/.local/share/icons), where
# they shadow the system theme without sudo and survive papirus updates.
# Takes a color: a stock Papirus folder color (blue, yellow, brown, ...)
# is copied over the default names, and "mustard" is generated by
# recoloring the yellow set. Re-run after a Papirus update adds icons.

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
. "$SCRIPT_DIR/utils.sh"

set -euo pipefail

# Papirus yellow -> mustard, body and shade
mustard_body_from="#f9bd30"
mustard_body_to="#cfa53a"
mustard_shade_from="#e19d00"
mustard_shade_to="#a67f1e"

generate_folder_overrides() {
    local color="$1" src_color theme src_root dst_root count
    if [ "$color" = "mustard" ]; then
        src_color="yellow"
    else
        src_color="$color"
    fi

    for theme in Papirus-Dark Papirus-Light; do
        src_root="/usr/share/icons/$theme"
        dst_root="$HOME/.local/share/icons/$theme"
        if [ ! -d "$src_root" ]; then
            warning "$theme is not installed, skipping"
            continue
        fi
        if [ ! -e "$src_root/48x48/places/folder-$src_color.svg" ]; then
            error "$theme has no folder-$src_color icons"
            exit 1
        fi

        rm -rf "$dst_root"
        count=0
        while IFS= read -r src; do
            local rel dst
            rel="${src#"$src_root"/}"
            # folder-<color>.svg -> folder.svg, folder-<color>-git.svg ->
            # folder-git.svg; the exact find patterns keep bluegrey and
            # friends from matching blue
            dst="$dst_root/${rel/folder-$src_color/folder}"
            mkdir -p "$(dirname "$dst")"
            if [ "$color" = "mustard" ]; then
                sed -e "s/$mustard_body_from/$mustard_body_to/g" \
                    -e "s/$mustard_shade_from/$mustard_shade_to/g" \
                    "$src" > "$dst"
            else
                cp -L "$src" "$dst"
            fi
            count=$((count + 1))
        done < <(find -L "$src_root" \( -name "folder-$src_color.svg" -o -name "folder-$src_color-*.svg" \))

        success "$theme: $count $color folder icons written to $dst_root"
    done
}

if [ "$0" = "${BASH_SOURCE[0]}" ]; then
    if [ $# -ne 1 ]; then
        error "usage: papirus-folder-overrides.sh <color|mustard>"
        exit 1
    fi
    generate_folder_overrides "$1"
fi
